    # date of birth copied into their own profile.
    op.execute("UPDATE profiles SET gender_identity = 'not_listed' WHERE gender_identity = 'other'")
    op.execute(
        "UPDATE profiles SET gender_identity = 'woman' WHERE gender_identity = 'trans_woman'"
    )
    op.execute("UPDATE profiles SET gender_identity = 'man' WHERE gender_identity = 'trans_man'")
    op.execute(
        "UPDATE profiles SET gender_identity = 'not_listed', "
        "gender_identity_other = COALESCE(NULLIF(gender_identity_other, ''), 'Intersex') "
        "WHERE gender_identity = 'intersex'"
    )
    op.execute(
        "UPDATE profiles SET date_of_birth = users.date_of_birth FROM users "
        "WHERE profiles.account_id = users.id AND profiles.is_self "
        "AND profiles.date_of_birth IS NULL AND users.date_of_birth IS NOT NULL"
    )

